<?php
declare(strict_types=1);
define('APP_ROOT',dirname(__DIR__));
$GLOBALS['app_config']=is_file(APP_ROOT.'/config.php')?(require APP_ROOT.'/config.php'):[];
if(session_status()!==PHP_SESSION_ACTIVE){$secure=(!empty($_SERVER['HTTPS'])&&$_SERVER['HTTPS']!=='off');session_set_cookie_params(['httponly'=>true,'samesite'=>'Lax','secure'=>$secure]);session_start();}
function config(string $key,mixed $default=null):mixed{return $GLOBALS['app_config'][$key]??$default;}
function db():PDO{static $pdo=null;static $ready=false;if($pdo instanceof PDO)return $pdo;if(!config('db_name'))throw new RuntimeException('Veritabanı yapılandırılmamış.');$pdo=new PDO('mysql:host='.config('db_host').';dbname='.config('db_name').';charset=utf8mb4',(string)config('db_user'),(string)config('db_pass'),[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC,PDO::ATTR_EMULATE_PREPARES=>false]);if(!$ready){$pdo->exec("CREATE TABLE IF NOT EXISTS inventory_codes(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,product_id BIGINT UNSIGNED NOT NULL,code_ciphertext LONGTEXT NOT NULL,code_nonce VARCHAR(64) NOT NULL,code_tag VARCHAR(64) NOT NULL,code_hash CHAR(64) NOT NULL,status VARCHAR(20) NOT NULL DEFAULT 'available',reserved_order_id BIGINT UNSIGNED NULL,reserved_until DATETIME NULL,sold_order_id BIGINT UNSIGNED NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY uq_product_code(product_id,code_hash),KEY idx_stock(product_id,status),KEY idx_reserved(reserved_until),CONSTRAINT fk_inventory_product FOREIGN KEY(product_id) REFERENCES products(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci");$pdo->exec("UPDATE orders o JOIN inventory_codes i ON i.reserved_order_id=o.id SET o.status='expired' WHERE i.status='reserved' AND i.reserved_until<NOW() AND o.payment_status<>'paid'");$pdo->exec("UPDATE inventory_codes i JOIN orders o ON o.id=i.reserved_order_id SET i.status='available',i.reserved_order_id=NULL,i.reserved_until=NULL WHERE i.status='reserved' AND i.reserved_until<NOW() AND o.payment_status<>'paid'");$ready=true;}return $pdo;}
function base_url():string{$p=str_replace('\\\\','/',dirname($_SERVER['SCRIPT_NAME']??'/'));$p=rtrim($p,'/');return $p===''||$p==='.'?'':$p;}
function url(string $path=''):string{return base_url().'/'.ltrim($path,'/');}
function absolute_url(string $path=''):string{$host=(string)($_SERVER['HTTP_HOST']??$_SERVER['SERVER_NAME']??'');if(!preg_match('/^[a-z0-9.-]+(?::[0-9]{1,5})?$/i',$host))throw new RuntimeException('Geçerli site alan adı belirlenemedi.');$https=(!empty($_SERVER['HTTPS'])&&$_SERVER['HTTPS']!=='off')||((int)($_SERVER['SERVER_PORT']??0)===443);return ($https?'https':'http').'://'.$host.url($path);}
function e(mixed $v):string{return htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}
function redirect(string $to):never{header('Location: '.$to);exit;}
function csrf_token():string{if(empty($_SESSION['_token']))$_SESSION['_token']=bin2hex(random_bytes(32));return $_SESSION['_token'];}
function csrf_check():void{if(!hash_equals(csrf_token(),(string)($_POST['_token']??''))){http_response_code(419);exit('Güvenlik doğrulaması başarısız.');}}
function flash(string $key,?string $message=null):?string{if($message!==null){$_SESSION['_flash'][$key]=$message;return null;}$v=$_SESSION['_flash'][$key]??null;unset($_SESSION['_flash'][$key]);return $v;}
function require_login(?string $role=null):void{$u=$_SESSION['user']??null;if(!$u)redirect(url('login'));if($role!==null&&($u['role']??'')!==$role){http_response_code(403);exit('Bu alana erişim yetkiniz yok.');}}
function render(string $view,array $data=[]):void{if(!isset($data['settings'])){$data['settings']=[];if(is_file(APP_ROOT.'/config.php'))foreach(db()->query('SELECT setting_key,setting_value FROM settings')->fetchAll() as $r)$data['settings'][$r['setting_key']]=$r['setting_value'];}if(!isset($data['categories'])&&is_file(APP_ROOT.'/config.php'))$data['categories']=db()->query("SELECT id,name,slug FROM categories WHERE status='active' ORDER BY sort_order,name")->fetchAll();if(!isset($data['menus'])&&is_file(APP_ROOT.'/config.php'))$data['menus']=db()->query("SELECT title,url FROM menus WHERE status='active' AND location='header' ORDER BY sort_order,id")->fetchAll();extract($data,EXTR_SKIP);require APP_ROOT.'/app/views/layout.php';}

function inventory_encrypt(string $plain):array{$key=hash('sha256',(string)config('app_key',config('db_pass')),true);$nonce=random_bytes(12);$tag='';$cipher=openssl_encrypt($plain,'aes-256-gcm',$key,OPENSSL_RAW_DATA,$nonce,$tag);if($cipher===false)throw new RuntimeException('Kod şifrelenemedi.');return [base64_encode($cipher),bin2hex($nonce),bin2hex($tag),hash('sha256',$plain)];}
function inventory_decrypt(array $row):string{$key=hash('sha256',(string)config('app_key',config('db_pass')),true);$plain=openssl_decrypt(base64_decode((string)$row['code_ciphertext'],true),'aes-256-gcm',$key,OPENSSL_RAW_DATA,hex2bin((string)$row['code_nonce']),hex2bin((string)$row['code_tag']));if($plain===false)throw new RuntimeException('Dijital kod çözülemedi.');return $plain;}
function fulfill_paid_order(int $orderId):void{$pdo=db();$pdo->beginTransaction();try{$st=$pdo->prepare("SELECT id,payment_status,status FROM orders WHERE id=? FOR UPDATE");$st->execute([$orderId]);$order=$st->fetch();if(!$order||$order['payment_status']!=='paid')throw new RuntimeException('Ödeme onayı bulunmayan sipariş teslim edilemez.');if($order['status']==='delivered'){$pdo->commit();return;}$st=$pdo->prepare("SELECT oi.product_id,oi.quantity,p.delivery_type FROM order_items oi LEFT JOIN products p ON p.id=oi.product_id WHERE oi.order_id=? ORDER BY oi.id");$st->execute([$orderId]);$hasManual=false;$hasAutomatic=false;foreach($st->fetchAll() as $item){if(($item['delivery_type']??'')!=='automatic'){$hasManual=true;continue;}$hasAutomatic=true;$q=(int)$item['quantity'];$sold=$pdo->prepare("SELECT COUNT(*) FROM inventory_codes WHERE product_id=? AND sold_order_id=? AND status='sold'");$sold->execute([(int)$item['product_id'],$orderId]);if((int)$sold->fetchColumn()>=$q)continue;$codes=$pdo->prepare("SELECT id FROM inventory_codes WHERE product_id=? AND reserved_order_id=? AND status='reserved' ORDER BY id LIMIT ".$q." FOR UPDATE");$codes->execute([(int)$item['product_id'],$orderId]);$ids=$codes->fetchAll(PDO::FETCH_COLUMN);if(count($ids)<$q)throw new RuntimeException('Ödeme alınmış sipariş için ayrılmış kod stoğu yetersiz.');$upd=$pdo->prepare("UPDATE inventory_codes SET status='sold',sold_order_id=?,reserved_order_id=NULL,reserved_until=NULL WHERE id=? AND status='reserved'");foreach($ids as $id)$upd->execute([$orderId,(int)$id]);}$newStatus=$hasManual?'partially_delivered':($hasAutomatic?'delivered':'processing');$pdo->prepare("UPDATE orders SET status=? WHERE id=?")->execute([$newStatus,$orderId]);$pdo->commit();}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();throw $e;}}
